<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class Report_model extends CI_Model{        public function enquiry_filter(){	$this->db->select('company.name,enquiry.*,company_details.*,admin.name AS admin_name');	        $check=0;        	if(!empty( $this->input->post('from'))){            $check++;            $from_date = explode('-',$this->input->post('from'));            $this->db->where('enquiry.date >=',$from_date[2].'-'.$from_date[1].'-'.$from_date[0]);	}	if(!empty( $this->input->post('to') )){            $check++;            $to_date = explode('-',$this->input->post('to'));            $this->db->where('enquiry.date <=',$to_date[2].'-'.$to_date[1].'-'.$to_date[0]);	        }	if(!empty( $this->input->post('agent_city') )){            $check++;            $this->db->where('company_details.city ',$this->input->post('agent_city'));	}        if(!empty( $this->input->post('company_details_id') )){            $check++;            $this->db->where('enquiry.company_details_id ',$this->input->post('company_details_id'));		}	if(!empty( $this->input->post('status') )){            $check++;            $this->db->where('followups.followup_status ',$this->input->post('status'));		}        if($check!=0)        {            }               $this->db->join('company_details','company_details.company_id = enquiry.company_details_id','');        $this->db->join('company','company.company_id = company_details.company','');        $this->db->join('followups','followups.enquiry_id = enquiry.id','LEFT');        $this->db->join('admin','admin.id = enquiry.file_handle_by','LEFT');        $this->db->order_by('enquiry.id','DESC');            $this->db->group_by('enquiry.enquiry_no');        $result = $this->db->get('enquiry');        //echo $this->db->last_query();exit;        return $result->result();	    }        public function edit_client(){	$this->db->select('company.name as client,company_details.*'); 	$this->db->join('company','company.company_id = company_details.company');	$this->db->where('company_details.company_id',$this->uri->segment(1));	$result = $this->db->get('company_details');	return $result->row();    }    public function update_client(){        $this->db->set('name', ucwords(strtolower($this->input->post('name'))));        $this->db->where('company_id',$this->input->post('company_id'));          $this->db->update('company');        $client = $this->db->affected_rows();                $branch_data = array(                            'country'		=>$this->security->xss_clean(ucwords(strtolower($this->input->post('country')))),            'state'			=>$this->security->xss_clean(ucwords(strtolower($this->input->post('state')))),            'city'			=>$this->security->xss_clean(ucwords(strtolower($this->input->post('city')))),            'address'		=>$this->security->xss_clean($this->input->post('address')),            'contact_person'=>$this->security->xss_clean(ucwords(strtolower($this->input->post('contact_person')))),            'contact_person_isd_code'=>$this->security->xss_clean($this->input->post('isd_codes')),            'contact_person_number'=>$this->security->xss_clean($this->input->post('contact_number')),            'email'			=>$this->security->xss_clean($this->input->post('email')),            'gstin'			=>$this->security->xss_clean($this->input->post('gstin')),            'user_id'               =>$this->session->userdata('id'),            'designation'           =>$this->security->xss_clean($this->input->post('designation'))        );        $this->db->where('company_id',$this->uri->segment(1));        $this->db->update('company_details',$branch_data);        $branch = $this->db->affected_rows();	if($client >0 || $branch > 0){            $this->session->set_flashdata('message','<div class="alert alert-success">Updated Successfully!</div>');            redirect('clients');	    	}else{            $this->session->set_flashdata('message','<div class="alert alert-danger">Error! You have not changed anything!</div>');            redirect($_SERVER['HTTP_REFERER']);	    	}    }    public function agentwise_report(){	$this->db->select('company.name,enquiry.*,company_details.*,admin.name AS admin_name');	        $check=0;        	if(!empty( $this->input->post('company_details_id')) && !empty( $this->input->post('agent_name'))){            $check++;            $this->db->where('enquiry.company_details_id ',$this->input->post('company_details_id'));	}	if(!empty( $this->input->post('booking_type') )){            $check++;            $this->db->where('enquiry.enquiry_abbr ',$this->input->post('booking_type'));	        }	if(!empty( $this->input->post('status') )){            $check++;            $this->db->where('enquiry.status ',$this->input->post('status'));	}        if(!empty( $this->input->post('from'))){            $check++;            $from_date = explode('-',$this->input->post('from'));            $this->db->where('enquiry.date >=',$from_date[2].'-'.$from_date[1].'-'.$from_date[0]);	}	if(!empty( $this->input->post('to') )){            $check++;            $to_date = explode('-',$this->input->post('to'));            $this->db->where('enquiry.date <=',$to_date[2].'-'.$to_date[1].'-'.$to_date[0]);	        }        if($check!=0)        {            }               $this->db->join('company_details','company_details.company_id = enquiry.company_details_id','');        $this->db->join('company','company.company_id = company_details.company','LEFT');        $this->db->join('followups','followups.enquiry_id = enquiry.id','LEFT');        $this->db->join('admin','admin.id = enquiry.file_handle_by','LEFT');        $this->db->order_by('enquiry.id','DESC');            $this->db->group_by('enquiry.enquiry_no');        $result = $this->db->get('enquiry');        //echo $this->db->last_query();exit;        return $result->result();	    }        }?>